def Run(argv=None):
    """standalone command line access point"""
    if argv is None:
        argv = sys.argv[1:]

    s_opts = "hdi"
    l_opts = (
        "help",
        "duplicates=",
        "ignore-comments",
        "ignore-imports",
        "ignore-docstrings",
        "ignore-signatures",
    )
    min_lines = DEFAULT_MIN_SIMILARITY_LINE
    ignore_comments = False
    ignore_docstrings = False
    ignore_imports = False
    ignore_signatures = False
    opts, args = getopt(argv, s_opts, l_opts)
    for opt, val in opts:
        if opt in ("-d", "--duplicates"):
            min_lines = int(val)
        elif opt in ("-h", "--help"):
            usage()
        elif opt in ("-i", "--ignore-comments"):
            ignore_comments = True
        elif opt in ("--ignore-docstrings",):
            ignore_docstrings = True
        elif opt in ("--ignore-imports",):
            ignore_imports = True
        elif opt in ("--ignore-signatures",):
            ignore_signatures = True
    if not args:
        usage(1)
    sim = Similar(
        min_lines, ignore_comments, ignore_docstrings, ignore_imports, ignore_signatures
    )
    for filename in args:
        with open(filename, encoding="utf-8") as stream:
            sim.append_stream(filename, stream)
    sim.run()
    sys.exit(0)

def run(self) -> None:
    """start looking for similarities and display results on stdout"""
    self._display_sims(self._compute_sims())

def _iter_sims(self) -> Generator[Commonality, None, None]:
    """iterate on similarities among all files, by making a cartesian
    product
    """
    for idx, lineset in enumerate(self.linesets[:-1]):
        for lineset2 in self.linesets[idx + 1 :]:
            yield from self._find_common(lineset, lineset2)

def _display_sims(
    self, similarities: List[Tuple[int, Set[LinesChunkLimits_T]]]
) -> None:
    """Display computed similarities on stdout"""
    report = self._get_similarity_report(similarities)
    print(report)

def _get_similarity_report(
    self, similarities: List[Tuple[int, Set[LinesChunkLimits_T]]]
) -> str:
    """Create a report from similarities"""
    report: str = ""
    duplicated_line_number: int = 0
    for number, couples in similarities:
        report += f"\n{number} similar lines in {len(couples)} files\n"
        couples_l = sorted(couples)
        line_set = start_line = end_line = None
        for line_set, start_line, end_line in couples_l:
            report += f"=={line_set.name}:[{start_line}:{end_line}]\n"
        if line_set:
            for line in line_set._real_lines[start_line:end_line]:
                report += f"   {line.rstrip()}\n" if line.rstrip() else "\n"
        duplicated_line_number += number * (len(couples_l) - 1)
    total_line_number: int = sum(len(lineset) for lineset in self.linesets)
    report += f"TOTAL lines={total_line_number} duplicates={duplicated_line_number} percent={duplicated_line_number * 100.0 / total_line_number:.2f}\n"
    return report

def _preprocess_options(run: Run, args: Sequence[str]) -> list[str]:
    """Preprocess options before full config parsing has started."""
    processed_args: list[str] = []

    i = 0
    while i < len(args):
        argument = args[i]
        if not argument.startswith("--"):
            processed_args.append(argument)
            i += 1
            continue

        try:
            option, value = argument.split("=", 1)
        except ValueError:
            option, value = argument, None

        if option not in PREPROCESSABLE_OPTIONS:
            processed_args.append(argument)
            i += 1
            continue

        takearg, cb = PREPROCESSABLE_OPTIONS[option]

        if takearg and value is None:
            i += 1
            if i >= len(args) or args[i].startswith("-"):
                raise ArgumentPreprocessingError(f"Option {option} expects a value")
            value = args[i]
        elif not takearg and value is not None:
            raise ArgumentPreprocessingError(f"Option {option} doesn't expects a value")

        cb(run, value)
        i += 1

    return processed_args

def _set_verbose_mode(run: Run, value: str | None) -> None:
    assert value is None
    run.verbose = True


def _enable_all_extensions(run: Run, value: str | None) -> None:
    """Enable all extensions."""
    assert value is None
    for filename in Path(extensions.__file__).parent.iterdir():
        if filename.suffix == ".py" and not filename.stem.startswith("_"):
            extension_name = f"pylint.extensions.{filename.stem}"
            if extension_name not in run._plugins:
                run._plugins.append(extension_name)


PREPROCESSABLE_OPTIONS: dict[
    str, tuple[bool, Callable[[Run, str | None], None]]
] = {  # pylint: disable=consider-using-namedtuple-or-dataclass
    "--init-hook": (True, _init_hook),
    "--rcfile": (True, _set_rcfile),
    "--output": (True, _set_output),
    "--load-plugins": (True, _add_plugins),
    "--verbose": (False, _set_verbose_mode),
    "--enable-all-extensions": (False, _enable_all_extensions),
}

def parse_config_file(
    self, file_path: Path | None
) -> tuple[dict[str, str], list[str]]:
    """Parse a config file and return str-str pairs."""
    if file_path is None:
        if self.verbose_mode:
            print(
                "No config file found, using default configuration", file=sys.stderr
            )
        return {}, []

    file_path = Path(os.path.expandvars(file_path)).expanduser()
    if not file_path.exists():
        raise OSError(f"The config file {file_path} doesn't exist!")

    if self.verbose_mode:
        print(f"Using config file {file_path}", file=sys.stderr)

    try:
        if file_path.suffix == ".toml":
            return self._parse_toml_file(file_path)
        return self._parse_ini_file(file_path)
    except (configparser.Error, tomllib.TOMLDecodeError) as e:
        self.linter.add_message("config-parse-error", line=0, args=str(e))
        return {}, []

